"use client";

import { FormEvent, useEffect, useState } from "react";
import type { Viewer } from "../db/access";
import { AdminConfiguration, AdminMessages, ContactMoya, OnboardingGate, ProgramDay, ToolCards } from "./project90-features";
import { ProfessionalManager, ProfessionalOverview, StudentRecords } from "./professional-panels";

type Row = Record<string, unknown>;
type AppData = { viewer: Viewer; participants?: Row[]; professionals?: Row[]; participantResponses?: Row[]; userWorkoutOverrides?: Row[]; programs?: Row[]; exercises?: Row[]; workouts?: Row[]; workoutBlocks?: Row[]; workoutExercises?: Row[]; content?: Row[]; sessions?: Row[]; profile?: Row; nutrition?: Row | null; checkpoints?: Row[]; metrics?: Row[]; reviewCheckpoints?: Row[]; reviewMetrics?: Row[]; settings?: Row[]; questions?: Row[]; responses?: Row[]; messages?: Row[]; meetings?: Row[]; meeting?: Row | null; assignedProgramId?: string | null };
type Modal = null | "participant" | "professional" | "program" | "workout" | "workout-edit" | "block" | "block-edit" | "exercise" | "exercise-edit" | "attach" | "attach-edit" | "nutrition" | "content" | "session" | "session-edit" | "participant-edit" | "adherence";
type ReviewMode = "admin" | "nutrition" | "training" | "participant";

const adminNav = ["Resumen", "Participantes", "Respuestas", "Profesionales", "Programas", "Nutrición", "Contenido", "Sesiones", "Reuniones 1:1", "Mensajes", "Configuración"];
const participantNav = ["Inicio", "Mi Semana", "Entrenamiento", "Alimentación", "Sesiones", "Reunión 1:1", "Progreso", "Aprender", "Escríbele al Moya"];
const iconMap: Record<string,string> = { Resumen:"⌂",Participantes:"◎",Alumnos:"◎",Respuestas:"☷",Profesionales:"♙",Programas:"↗",Nutrición:"◒",Contenido:"◇",Sesiones:"▣","Reuniones 1:1":"◉","Reunión 1:1":"◉",Mensajes:"✉",Configuración:"⚙",Inicio:"⌂","Mi Semana":"☷",Entrenamiento:"↗",Alimentación:"◒",Progreso:"◎",Aprender:"◇","Escríbele al Moya":"✉" };

export function FunctionalApp({ initialViewer }: { initialViewer: Viewer }) {
  const [data,setData]=useState<AppData|null>(null); const [screen,setScreen]=useState(initialViewer.role==="participant"?"Inicio":"Resumen");
  const [loading,setLoading]=useState(true); const [modal,setModal]=useState<Modal>(null); const [context,setContext]=useState<Row>({});
  const [toast,setToast]=useState(""); const [error,setError]=useState(""); const [selected,setSelected]=useState<string[]>([]);
  const [reviewMode,setReviewMode]=useState<ReviewMode>("admin");const [reviewParticipantId,setReviewParticipantId]=useState("");
  const professionalType=initialViewer.professionalType||"both";const professionalNav=professionalType==="nutrition"?["Resumen","Alumnos","Nutrición"]:professionalType==="training"?["Resumen","Alumnos"]:["Resumen","Alumnos","Nutrición"];
  const reviewerNav=reviewMode==="participant"?participantNav:reviewMode==="training"?["Resumen","Alumnos"]:["Resumen","Alumnos","Nutrición"];
  const nav=initialViewer.role==="reviewer"?(reviewMode==="admin"?adminNav:reviewerNav):initialViewer.role==="participant"?participantNav:initialViewer.role==="professional"?professionalNav:adminNav;
  async function load(silent=false){if(!silent)setLoading(true);const res=await fetch("/api/app",{cache:"no-store"});const json=await res.json();if(!res.ok)setError(json.error||"No fue posible cargar");else setData(json);if(!silent)setLoading(false)}
  // Initial synchronization plus a refresh when the user returns to the tab.
  useEffect(()=>{load();const refresh=()=>load(true);window.addEventListener("focus",refresh);return()=>window.removeEventListener("focus",refresh)},[]);
  async function act(payload:Row){setError("");if(data?.viewer.role==="reviewer"){const message="Perfil Revisor: esta vista es de solo lectura.";setError(message);throw new Error(message)}const res=await fetch("/api/app",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});const json=await res.json();if(!res.ok){setError(json.error||"No fue posible guardar");throw new Error(json.error)}setToast(json.message||"Guardado");setTimeout(()=>setToast(""),2600);await load();return json}
  function open(next:Modal,row:Row={}){setContext(row);setError("");setModal(next)}
  if(loading&&!data)return <div className="app-loading"><img className="loading-logo" src="/proyecto-90-logo-transparente.png" alt="Proyecto 90"/><p>Preparando tu Proyecto 90…</p></div>;
  if(!data)return <div className="app-loading"><p>{error||"No fue posible cargar la plataforma."}</p><button className="primary" onClick={()=>load()}>Reintentar</button></div>;
  const activeReviewParticipant=reviewParticipantId||String(data.participants?.[0]?.id||"");
  const participantReviewData=data.viewer.role==="reviewer"?buildReviewParticipantData(data,activeReviewParticipant):null;
  const professionalReviewData=data.viewer.role==="reviewer"?{...data,viewer:{...data.viewer,role:"professional" as const,professionalType:reviewMode}}:null;
  return <div className={`app-shell ${data.viewer.role==="participant"||data.viewer.role==="reviewer"&&reviewMode==="participant"?"participant-shell":"admin-shell"} ${data.viewer.role==="reviewer"?"reviewer-shell":""}`}>
    <aside className="sidebar"><button className="brand" onClick={()=>setScreen(nav[0])}><img className="brand-logo" src="/proyecto-90-logo-transparente.png" alt="Proyecto 90"/><span><strong>PLATAFORMA</strong><small>90 DÍAS · GENERACIÓN 01</small></span></button><nav>{nav.map(x=><button key={x} className={screen===x?"active":""} onClick={()=>setScreen(x)}><span className="nav-icon">{iconMap[x]}</span>{x}</button>)}</nav><div className="sidebar-spacer"/><div className="side-quote"><span>“</span><p><strong>No buscamos hacerlo perfecto.</strong><br/>Buscamos hacerlo parte de tu vida.</p><small>90 días. Un compromiso contigo.</small></div><div className="profile-mini"><span className="avatar">{initials(data.viewer.name)}</span><span><strong>{data.viewer.name}</strong><small>{roleLabel(data.viewer.role)}</small></span></div></aside>
    <main><header className="topbar"><div className="mobile-brand"><img src="/proyecto-90-logo-transparente.png" alt="Proyecto 90"/><b>PROYECTO 90</b></div><div className="top-actions">{data.viewer.role==="reviewer"?<span className="reviewer-badge">◉ Solo lectura</span>:<span className="secure-pill">● Datos guardados</span>}<span className="user-email">{data.viewer.email}</span><a className="logout" href="/signout-with-chatgpt?return_to=/">Salir</a></div></header>{data.viewer.role==="reviewer"&&<ReviewerToolbar mode={reviewMode} setMode={next=>{setReviewMode(next);setScreen(next==="participant"?"Inicio":"Resumen")}} people={data.participants||[]} participantId={activeReviewParticipant} setParticipantId={id=>{setReviewParticipantId(id);setScreen("Inicio")}}/>}<div className="page-wrap">
      {data.viewer.role==="reviewer"
        ? reviewMode==="admin"
          ? <AdminArea data={data} screen={screen} open={open} act={act} selected={selected} setSelected={setSelected}/>
          : reviewMode==="participant"&&participantReviewData
            ? <ParticipantArea data={participantReviewData} screen={screen} act={act}/>
            : professionalReviewData&&<ProfessionalArea data={professionalReviewData} screen={screen} open={open} act={act}/>
        : data.viewer.role==="participant"
        ? <ParticipantArea data={data} screen={screen} act={act}/>
        : data.viewer.role==="professional"
          ? <ProfessionalArea data={data} screen={screen} open={open} act={act}/>
          : <AdminArea data={data} screen={screen} open={open} act={act} selected={selected} setSelected={setSelected}/>}
    </div><nav className="mobile-nav">{nav.map(x=><button key={x} className={screen===x?"active":""} onClick={()=>setScreen(x)}><span>{iconMap[x]}</span><small>{x}</small></button>)}</nav></main>
    {data.viewer.role==="participant"&&!onboardingIsComplete(data)&&<OnboardingGate questions={data.questions} responses={data.responses} act={act}/>} {modal&&<Editor key={`${modal}-${String(context.id||"")}`} modal={modal} context={context} data={data} close={()=>setModal(null)} act={act}/>} {toast&&<div className="toast">✓ {toast}</div>} {error&&<div className="error-toast">{error}<button onClick={()=>setError("")}>×</button></div>}
  </div>
}

function ReviewerToolbar({mode,setMode,people,participantId,setParticipantId}:{mode:ReviewMode;setMode:(mode:ReviewMode)=>void;people:Row[];participantId:string;setParticipantId:(id:string)=>void}){
  const modes:[ReviewMode,string][]=[["admin","Administrador"],["nutrition","Nutricionista"],["training","Preparador físico"],["participant","Alumno"]];
  return <section className="reviewer-toolbar"><div><span>PERFIL REVISOR</span><b>Cambiar vista</b></div><nav>{modes.map(([value,label])=><button key={value} className={mode===value?"active":""} onClick={()=>setMode(value)}>{label}</button>)}</nav>{mode==="participant"&&<label>Alumno a revisar<select value={participantId} onChange={e=>setParticipantId(e.target.value)}>{people.map(row=><option key={String(row.id)} value={String(row.id)}>{`${row.first_name||""} ${row.last_name||""}`.trim()||String(row.email)}</option>)}</select></label>}<small>Solo lectura: ningún cambio puede guardarse.</small></section>
}

function buildReviewParticipantData(data:AppData,userId:string):AppData|null{
  const person=(data.participants||[]).find(row=>String(row.id)===userId)||(data.participants||[])[0];if(!person)return null;
  const approved=person.nutrition_id&&String(person.review_status)==="approved"?{id:person.nutrition_id,user_id:person.id,calories:person.calories,protein:person.protein,carbs:person.carbs,fats:person.fats,objective:person.nutrition_objective,pdf_key:person.pdf_key,notes:person.nutrition_notes,review_date:person.review_date,review_status:person.review_status}:null;
  return {...data,viewer:{id:String(person.id),role:"participant",name:`${person.first_name||""} ${person.last_name||""}`.trim()||String(person.email),email:String(person.email),status:String(person.status||"active")},profile:{...person,weight:person.initial_weight},nutrition:approved,checkpoints:(data.reviewCheckpoints||[]).filter(row=>String(row.user_id)===String(person.id)),metrics:(data.reviewMetrics||[]).filter(row=>String(row.user_id)===String(person.id)),responses:(data.participantResponses||[]).filter(row=>String(row.user_id)===String(person.id)),userWorkoutOverrides:(data.userWorkoutOverrides||[]).filter(row=>String(row.user_id)===String(person.id)),assignedProgramId:String(person.program_id||"")||null,meeting:(data.meetings||[]).find(row=>String(row.user_id)===String(person.id))||null};
}

function ProfessionalArea({data,screen,open,act}:{data:AppData;screen:string;open:(m:Modal,r?:Row)=>void;act:(r:Row)=>Promise<unknown>}){
  if(screen==="Alumnos")return <StudentRecords data={data} act={act}/>;
  if(screen==="Nutrición")return <NutritionQueue people={data.participants||[]} open={open} act={act} viewer={data.viewer}/>;
  return <ProfessionalOverview data={data}/>;
}

function AdminArea({data,screen,open,act,selected,setSelected}:{data:AppData;screen:string;open:(m:Modal,r?:Row)=>void;act:(r:Row)=>Promise<unknown>;selected:string[];setSelected:(x:string[])=>void}){
  const people=data.participants||[]; const programs=data.programs||[];
  if(screen==="Participantes")return <Participants people={people} programs={programs} selected={selected} setSelected={setSelected} open={open} act={act}/>;
  if(screen==="Respuestas")return <StudentRecords data={data} act={act}/>;
  if(screen==="Profesionales")return <ProfessionalManager rows={data.professionals} open={open}/>;
  if(screen==="Programas")return <ProgramManager data={data} open={open}/>;
  if(screen==="Nutrición")return <NutritionQueue people={people} open={open} act={act} viewer={data.viewer}/>;
  if(screen==="Contenido")return <ContentManager rows={data.content||[]} open={open}/>;
  if(screen==="Sesiones")return <SessionManager rows={data.sessions||[]} open={open} act={act}/>;
  if(screen==="Reuniones 1:1")return <MeetingManager rows={data.meetings||[]} act={act}/>;
  if(screen==="Mensajes")return <AdminMessages rows={data.messages}/>;
  if(screen==="Configuración")return <AdminConfiguration settings={data.settings} questions={data.questions} act={act}/>;
  const pendingNutrition=people.filter(x=>!x.nutrition_id).length; const noProgram=people.filter(x=>!x.program_id).length; const risk=people.filter(x=>Number(x.adherence||100)<40).length;const pendingMeetings=(data.meetings||[]).filter(x=>x.status==="pending").length;
  return <><Title eyebrow="PROYECTO 90 · OPERACIÓN" title={`Hola, ${first(data.viewer.name)}`} copy="Esto es lo que requiere atención hoy." action={<button className="primary" onClick={()=>open("participant")}>＋ Crear participante</button>}/><section className="stats-grid five"><Metric label="Participantes" value={String(people.length)} note="Registrados"/><Metric label="Activos" value={String(people.filter(x=>x.status==="active").length)} note="Dentro del programa" green/><Metric label="Sin programa" value={String(noProgram)} note="Requieren asignación"/><Metric label="Nutrición pendiente" value={String(pendingNutrition)} note="Completar plan"/><Metric label="Adherencia baja" value={String(risk)} note="Menos de 40%"/></section>{pendingMeetings>0&&<article className="meeting-admin-notice"><span>◉</span><div><b>{pendingMeetings} {pendingMeetings===1?"solicitud de reunión pendiente":"solicitudes de reunión pendientes"}</b><p>Revísala en “Reuniones 1:1” para aprobar, rechazar o proponer un nuevo horario.</p></div></article>}<section className="attention"><div className="attention-head"><div><span className="pulse">!</span><div><span className="eyebrow">REQUIERE ATENCIÓN</span><h2>{noProgram+pendingNutrition+risk+pendingMeetings} acciones pendientes</h2></div></div></div><div className="attention-grid"><button onClick={()=>open("participant")}><span className="attention-icon">＋</span><div><h3>Crear alumno</h3><p>Correo, perfil y ruta inicial</p></div><em>›</em></button><button onClick={()=>programs[0]&&open("workout",programs[0])}><span className="attention-icon">↗</span><div><h3>Agregar rutina</h3><p>Dentro de un programa</p></div><em>›</em></button><button onClick={()=>open("exercise")}><span className="attention-icon nutrition">▶</span><div><h3>Agregar video técnico</h3><p>Biblioteca reutilizable</p></div><em>›</em></button></div></section><div className="section-heading"><div><span className="eyebrow">ÚLTIMOS REGISTROS</span><h2>Participantes</h2></div></div><PeopleTable rows={people.slice(0,6)} selected={[]} setSelected={()=>{}} open={open}/></>
}

function Participants({people,programs,selected,setSelected,open,act}:{people:Row[];programs:Row[];selected:string[];setSelected:(x:string[])=>void;open:(m:Modal,r?:Row)=>void;act:(r:Row)=>Promise<unknown>}){
  const [program,setProgram]=useState(""); return <><Title eyebrow="GESTIÓN DE ALUMNOS" title="Participantes" copy="Crea perfiles, asigna programas y revisa el estado real de cada persona." action={<button className="primary" onClick={()=>open("participant")}>＋ Crear participante</button>}/>{selected.length>0&&<div className="bulk-bar"><b>{selected.length} seleccionados</b><select value={program} onChange={e=>setProgram(e.target.value)}><option value="">Asignar programa…</option>{programs.map(p=><option value={String(p.id)} key={String(p.id)}>{String(p.name)}</option>)}</select><button className="primary" disabled={!program} onClick={async()=>{await act({action:"program.assign",userIds:selected,programId:program});setSelected([]);setProgram("")}}>Asignar</button><button onClick={()=>setSelected([])}>Cancelar</button></div>}<PeopleTable rows={people} selected={selected} setSelected={setSelected} open={open}/></>
}

function PeopleTable({rows,selected,setSelected,open}:{rows:Row[];selected:string[];setSelected:(x:string[])=>void;open:(m:Modal,r?:Row)=>void}){return <div className="table-card"><table><thead><tr><th><input type="checkbox" aria-label="Seleccionar todos" checked={rows.length>0&&selected.length===rows.length} onChange={e=>setSelected(e.target.checked?rows.map(x=>String(x.id)):[])}/></th><th>Participante</th><th>Avance</th><th>Peso inicial</th><th>Último peso</th><th>Estado</th><th>Rutina asignada</th><th>Nutrición</th><th>Adherencia Firme</th><th></th></tr></thead><tbody>{rows.map(p=>{const initial=numberValue(p.initial_weight);const latest=numberValue(p.latest_weight);const change=initial!=null&&latest!=null?latest-initial:null;return <tr key={String(p.id)}><td><input type="checkbox" checked={selected.includes(String(p.id))} onChange={e=>setSelected(e.target.checked?[...selected,String(p.id)]:selected.filter(x=>x!==p.id))}/></td><td><div className="person"><span className="avatar">{initials(`${p.first_name||""} ${p.last_name||""}`)}</span><div><b>{`${p.first_name||""} ${p.last_name||""}`.trim()||String(p.email)}</b><small>{String(p.email)}</small></div></div></td><td><ProgramDay day={p.program_day} graduated={Boolean(p.graduated)}/></td><td>{initial!=null?<b>{formatWeight(initial)}</b>:<span className="muted">Sin dato</span>}</td><td>{latest!=null?<div className="weight-cell"><b>{formatWeight(latest)}</b>{change!=null&&Math.abs(change)>=0.05&&<small className={change<0?"weight-down":"weight-up"}>{change>0?"+":""}{change.toFixed(1)} kg</small>}</div>:<span className="muted">Sin reporte</span>}</td><td><Status text={String(p.status||"invited")}/></td><td>{p.program_name?String(p.program_name):<span className="muted">Sin asignar</span>}</td><td>{p.nutrition_id?<Status text={String(p.review_status||"pending_review")}/>:<Status text="Sin plan"/>}</td><td>{p.adherence==null?<button className="row-action" onClick={()=>open("adherence",p)}>Cargar %</button>:<button className={Number(p.adherence)<40?"adherence-button risk":"adherence-button"} onClick={()=>open("adherence",p)}>{String(p.adherence)}% · editar</button>}</td><td><button className="row-action" onClick={()=>open("participant-edit",p)}>Editar ›</button></td></tr>})}</tbody></table></div>}

function ProgramManager({data,open}:{data:AppData;open:(m:Modal,r?:Row)=>void}){
  const programs=data.programs||[];
  const [active,setActive]=useState(String(programs[0]?.id||""));
  const program=programs.find(x=>String(x.id)===active)||programs[0];
  const workouts=(data.workouts||[]).filter(x=>String(x.program_id)===String(program?.id));
  const links=data.workoutExercises||[];
  const blocks=data.workoutBlocks||[];
  const exercises=data.exercises||[];
  const missingVideos=exercises.filter(x=>!x.youtube_url).length;
  return <><Title eyebrow="RUTAS REUTILIZABLES" title="Programas y rutinas" copy="Organiza cada sesión por bloques. Cada cambio se sincroniza automáticamente con los participantes." action={<button className="primary" onClick={()=>open("program")}>＋ Nuevo programa</button>}/><div className="program-tabs">{programs.map(p=><button className={String(p.id)===String(program?.id)?"active":""} key={String(p.id)} onClick={()=>setActive(String(p.id))}><b>{String(p.name)}</b><small>{String(p.workout_count||0)} rutinas · {String(p.participant_count||0)} alumnos</small></button>)}</div>{program&&<><div className="section-heading"><div><span className="eyebrow">{String(program.level)} · {String(program.location)}</span><h2>{String(program.name)}</h2></div><div className="inline-actions"><button className="secondary" onClick={()=>open("exercise")}>＋ Ejercicio / video</button><button className="primary" onClick={()=>open("workout",program)}>＋ Agregar rutina</button></div></div>{workouts.length===0?<Empty title="Aún no hay rutinas" copy="Crea la primera rutina del programa y luego agrega sus bloques." action={<button className="primary" onClick={()=>open("workout",program)}>Crear primera rutina</button>}/>:<section className="workout-admin-grid">{workouts.map(w=><AdminWorkoutCard key={String(w.id)} workout={w} blocks={blocks} links={links} open={open}/>)}</section>}<div className="section-heading"><div><span className="eyebrow">BIBLIOTECA REUTILIZABLE</span><h2>Ejercicios</h2>{missingVideos>0&&<p className="video-library-alert">{missingVideos} ejercicios necesitan un video antes de poder agregarse a nuevas rutinas.</p>}</div><button className="secondary" onClick={()=>open("exercise")}>＋ Nuevo ejercicio</button></div>{exercises.length===0?<Empty title="Biblioteca vacía" copy="Agrega ejercicios con su video y guía técnica."/>:<section className="content-table panel">{exercises.map(x=><div className={`content-row ${!x.youtube_url?"missing-video":""}`} key={String(x.id)}><span className="icon-tile">▶</span><div><h3>{String(x.name)}</h3><p>{String(x.category||"Sin categoría")} · {String(x.level||"Sin nivel")}</p></div>{x.youtube_url?<a href={String(x.youtube_url)} target="_blank" rel="noreferrer">Ver técnica ↗</a>:<span className="video-missing-label">Falta video</span>}<button onClick={()=>open("exercise-edit",x)}>{x.youtube_url?"Editar":"Agregar video"}</button></div>)}</section>}</>}</>
}

function AdminWorkoutCard({workout,blocks,links,open}:{workout:Row;blocks:Row[];links:Row[];open:(m:Modal,r?:Row)=>void}){
  const workoutBlocks=blocks.filter(x=>String(x.workout_id)===String(workout.id));
  const workoutLinks=links.filter(x=>String(x.workout_id)===String(workout.id));
  const known=new Set(workoutBlocks.map(x=>String(x.id)));
  const ungrouped=workoutLinks.filter(x=>!x.block_id||!known.has(String(x.block_id)));
  return <article className="workout-admin"><div className="workout-head"><div><span className="eyebrow">MES {String(workout.month)} · SEMANA {String(workout.week)}</span><h3>{String(workout.name)}</h3></div><div className="inline-actions"><button className="secondary" onClick={()=>open("workout-edit",workout)}>Editar rutina</button><button className="primary" onClick={()=>open("block",workout)}>＋ Agregar bloque</button></div></div>{workout.progression&&<p className="progression-note"><b>Progresión semanal</b>{String(workout.progression)}</p>}{workoutBlocks.map((block,i)=><AdminWorkoutBlock key={String(block.id)} block={block} index={i} links={workoutLinks.filter(x=>String(x.block_id)===String(block.id))} workout={workout} open={open}/>)}{ungrouped.length>0&&<section className="workout-block ungrouped"><div className="workout-block-head"><div><span className="block-order">SIN BLOQUE</span><h4>Ejercicios adicionales</h4></div><button className="secondary" onClick={()=>open("attach",workout)}>＋ Agregar ejercicio</button></div>{ungrouped.map((x,i)=><AdminExerciseRow key={String(x.id)} item={x} index={i} open={open}/>)}</section>}{workoutBlocks.length===0&&ungrouped.length===0&&<Empty title="Arma la sesión por bloques" copy="Agrega un bloque como Calentamiento, Circuito o Finisher y define sus rondas y descansos." action={<button className="primary" onClick={()=>open("block",workout)}>＋ Primer bloque</button>}/>}</article>
}

function AdminWorkoutBlock({block,index,links,workout,open}:{block:Row;index:number;links:Row[];workout:Row;open:(m:Modal,r?:Row)=>void}){
  return <section className="workout-block"><div className="workout-block-head"><div><span className="block-order">BLOQUE {index+1}</span><h4>{String(block.name)}</h4><BlockSummary block={block}/></div><div className="inline-actions"><button className="row-action" onClick={()=>open("block-edit",block)}>Editar bloque</button><button className="secondary" onClick={()=>open("attach",{...workout,block_id:block.id,block_name:block.name})}>＋ Agregar ejercicio</button></div></div>{block.notes&&<p className="block-instructions">{String(block.notes)}</p>}<div className="block-exercises">{links.map((x,i)=><AdminExerciseRow key={String(x.id)} item={x} index={i} open={open}/>)}</div>{links.length===0&&<p className="empty-copy">Este bloque aún no tiene ejercicios.</p>}</section>
}

function AdminExerciseRow({item,index,open}:{item:Row;index:number;open:(m:Modal,r?:Row)=>void}){return <div className="admin-exercise-row"><span>{index+1}</span><div><b>{String(item.exercise_name)}</b><small>{exerciseDetail(item)}{usefulExerciseNote(item)?` · ${usefulExerciseNote(item)}`:""}</small></div>{item.youtube_url&&<a href={String(item.youtube_url)} target="_blank" rel="noreferrer">Video ↗</a>}<button className="row-action" onClick={()=>open("attach-edit",item)}>Editar</button></div>}


function NutritionQueue({people,open,act,viewer}:{people:Row[];open:(m:Modal,r?:Row)=>void;act:(x:Row)=>Promise<unknown>;viewer:Viewer}){
  const [statusFilter,setStatusFilter]=useState<"all"|"missing"|"review"|"approved">("all");const [studentFilter,setStudentFilter]=useState("all");
  const missing=people.filter(x=>nutritionStatusKey(x)==="missing");const review=people.filter(x=>nutritionStatusKey(x)==="review");const approved=people.filter(x=>nutritionStatusKey(x)==="approved");const canReview=viewer.role==="professional"&&["nutrition","both"].includes(viewer.professionalType||"both");
  const statusPeople=statusFilter==="all"?people:people.filter(x=>nutritionStatusKey(x)===statusFilter);const visiblePeople=studentFilter==="all"?statusPeople:statusPeople.filter(x=>String(x.id)===studentFilter);
  async function decide(row:Row,decision:"approved"|"rejected"){const note=decision==="rejected"?window.prompt("Indica qué debe corregirse antes de aprobar el plan:")||"":"";if(decision==="rejected"&&!note)return;await act({action:"nutrition.review",id:row.nutrition_id,decision,note})}
  function chooseStatus(value:"all"|"missing"|"review"|"approved"){setStatusFilter(value);setStudentFilter("all")}
  return <><Title eyebrow={canReview?"REVISIÓN NUTRICIONAL":"PLANES PERSONALIZADOS"} title="Distribución de macronutrientes" copy={canReview?"Filtra por estado o alumno, edita la distribución y publica únicamente los planes aprobados.":"Filtra por estado o alumno para revisar rápidamente cada distribución."}/><section className="nutrition-filter-toolbar"><div className="nutrition-status-filters" aria-label="Filtrar por estado"><button className={statusFilter==="all"?"active":""} onClick={()=>chooseStatus("all")}><span>Todos</span><b>{people.length}</b></button><button className={statusFilter==="missing"?"active missing":"missing"} onClick={()=>chooseStatus("missing")}><span>Sin calcular</span><b>{missing.length}</b></button><button className={statusFilter==="review"?"active review":"review"} onClick={()=>chooseStatus("review")}><span>Por revisar</span><b>{review.length}</b></button><button className={statusFilter==="approved"?"active approved":"approved"} onClick={()=>chooseStatus("approved")}><span>Aprobados</span><b>{approved.length}</b></button></div><label className="nutrition-student-filter"><span>Alumno</span><select value={studentFilter} onChange={e=>setStudentFilter(e.target.value)}><option value="all">Todos los alumnos ({statusPeople.length})</option>{statusPeople.map(p=><option value={String(p.id)} key={String(p.id)}>{`${p.first_name||""} ${p.last_name||""}`.trim()||String(p.email)}</option>)}</select></label></section><div className="nutrition-results-line"><span>{visiblePeople.length} {visiblePeople.length===1?"alumno":"alumnos"}</span><small>{statusFilter==="all"?"Todos los estados":statusFilter==="missing"?"Sin cálculo de macros":statusFilter==="review"?"Pendientes de revisión o corrección":"Planes aprobados y visibles"}</small></div><section className="nutrition-plan-list">{visiblePeople.map(p=><NutritionPlanCard key={String(p.id)} participant={p} open={open} canReview={canReview} decide={decide}/>)}{visiblePeople.length===0&&<article className="empty-state"><h2>No hay alumnos con este filtro</h2><p>Prueba con otro estado o selecciona “Todos”.</p></article>}</section></>
}

function NutritionPlanCard({participant:p,open,canReview,decide}:{participant:Row;open:(m:Modal,r?:Row)=>void;canReview:boolean;decide:(row:Row,decision:"approved"|"rejected")=>Promise<void>}){
  return <article className="nutrition-plan-card"><header className="nutrition-plan-head"><div className="person"><span className="avatar large">{initials(`${p.first_name||""} ${p.last_name||""}`)}</span><div><b>{`${p.first_name||""} ${p.last_name||""}`.trim()||String(p.email)}</b><small>{String(p.email)}</small></div></div><div className="nutrition-plan-state"><Status text={p.nutrition_id?String(p.review_status||"pending_review"):"Sin plan"}/>{p.review_note&&<small className="review-note">{String(p.review_note)}</small>}</div></header>{p.nutrition_id?<><div className="nutrition-plan-summary"><div><small>OBJETIVO</small><b>{String(p.nutrition_objective||p.objective||"Sin definir")}</b></div><div><small>PESO DEL FORMULARIO</small><b>{nutritionWeight(p)?formatWeight(nutritionWeight(p)):"Sin dato"}</b></div><div><small>ENERGÍA SUGERIDA</small><b>{formatNumber(Number(p.calories||0),0)} kcal</b></div><div><small>PLAN ADJUNTO</small>{p.pdf_key?<a href={`/api/files?key=${encodeURIComponent(String(p.pdf_key))}`} target="_blank">Ver PDF ↗</a>:<b>Sin adjunto</b>}</div></div><MacroDistributionTable plan={p} weight={nutritionWeight(p)}/></>:<div className="nutrition-empty-plan"><p>Aún no se ha calculado la distribución de este participante.</p></div>}<footer className="nutrition-plan-actions"><button className={p.nutrition_id?"secondary":"primary"} onClick={()=>open("nutrition",p)}>{p.nutrition_id?"Editar distribución":"Crear distribución"}</button>{canReview&&p.nutrition_id&&String(p.review_status)!=="approved"&&<><button className="primary" onClick={()=>decide(p,"approved")}>✓ Aprobar y publicar</button><button className="danger-button" onClick={()=>decide(p,"rejected")}>Rechazar</button></>}</footer></article>
}

function MacroDistributionTable({plan,weight,className=""}:{plan:Row;weight:number;className?:string}){
  const calories=Number(plan.calories||0);const macros=[{name:"Proteínas",grams:Number(plan.protein||0),factor:4},{name:"Carbohidratos",grams:Number(plan.carbs||0),factor:4},{name:"Lípidos (grasas)",grams:Number(plan.fats||0),factor:9}];
  return <div className={`macro-distribution-wrap ${className}`}><table className="macro-distribution"><thead><tr><th>Macronutriente</th><th>%</th><th>Energía estimada</th><th>Gramos</th><th>g/kg</th></tr></thead><tbody>{macros.map(m=>{const energy=m.grams*m.factor;return <tr key={m.name}><th>{m.name}</th><td>{calories>0?`${formatNumber(energy/calories*100,1)}%`:"—"}</td><td>{formatNumber(energy,0)} kcal</td><td><b>{formatNumber(m.grams,1)} g</b></td><td>{weight>0?formatNumber(m.grams/weight,2):"—"}</td></tr>})}</tbody><tfoot><tr><th>Total calculado</th><td>{calories>0?`${formatNumber(macros.reduce((sum,m)=>sum+m.grams*m.factor,0)/calories*100,1)}%`:"—"}</td><td>{formatNumber(macros.reduce((sum,m)=>sum+m.grams*m.factor,0),0)} kcal</td><td colSpan={2}>Referencia diaria</td></tr></tfoot></table></div>
}

function ContentManager({rows,open}:{rows:Row[];open:(m:Modal,r?:Row)=>void}){return <><Title eyebrow="BIBLIOTECA CENTRAL" title="Clases y contenido" copy="Marca una clase como obligatoria para liberarla desde el primer día a todos los participantes." action={<button className="primary" onClick={()=>open("content")}>＋ Nueva clase</button>}/>{rows.length===0?<Empty title="Aún no hay contenido" copy="Publica el primer módulo de hábitos, nutrición o entrenamiento." action={<button className="primary" onClick={()=>open("content")}>Publicar contenido</button>}/>:<section className="content-table panel">{rows.map(x=><div className="content-row" key={String(x.id)}><span className="icon-tile">▶</span><div><h3>{String(x.title)}</h3><p>{String(x.category)} · {String(x.description||"")}</p></div>{x.video_url&&<a href={String(x.video_url)} target="_blank" rel="noreferrer">Ver video ↗</a>}<Status text={Number(x.is_required)?"Obligatoria":"Publicada"}/></div>)}</section>}</>}
function SessionManager({rows,open,act}:{rows:Row[];open:(m:Modal,r?:Row)=>void;act:(x:Row)=>Promise<unknown>}){async function remove(row:Row){if(!window.confirm(`¿Eliminar la sesión “${String(row.title)}”? Esta acción también la quitará de la agenda de los alumnos.`))return;await act({action:"session.delete",id:row.id})}return <><Title eyebrow="AGENDA" title="Sesiones" copy="Crea, edita o elimina sesiones. Los cambios se reflejan en la agenda de los alumnos." action={<button className="primary" onClick={()=>open("session")}>＋ Nueva sesión</button>}/>{rows.length===0?<Empty title="No hay sesiones" copy="Crea la primera sesión de la generación." action={<button className="primary" onClick={()=>open("session")}>Crear sesión</button>}/>:<section className="session-list">{rows.map(x=><article className="next-session admin-session" key={String(x.id)}><SessionDate row={x}/><div><h3>{String(x.title)}</h3><p>{String(x.professional||"Sin profesional")} · {formatSessionDate(x.starts_at)}</p></div>{x.link&&<a className="secondary" href={String(x.link)} target="_blank" rel="noreferrer">Abrir enlace ↗</a>}<div className="session-actions"><button className="secondary" onClick={()=>open("session-edit",x)}>Editar</button><button className="danger-button" onClick={()=>remove(x)}>Eliminar</button></div></article>)}</section>}</>}

function SessionDate({row}:{row:Row}){const date=new Date(String(row.starts_at));return <div className="calendar-box"><b>{date.getDate()}</b><span>{date.toLocaleDateString("es-CL",{month:"short"}).toUpperCase()}</span></div>}

function ParticipantSessions({rows}:{rows:Row[]}){return <><Title eyebrow="AGENDA PROYECTO 90" title="Próximas sesiones" copy="Encuentra aquí las siguientes charlas y encuentros del programa."/>{rows.length===0?<Empty title="No hay sesiones programadas" copy="Cuando el equipo publique una nueva fecha aparecerá automáticamente aquí."/>:<section className="participant-session-list">{rows.map((row,i)=><article className={`next-session participant-session ${i===0?"featured":""}`} key={String(row.id)}><SessionDate row={row}/><div><span className="eyebrow">{i===0?"PRÓXIMA SESIÓN":"MÁS ADELANTE"}</span><h3>{String(row.title)}</h3><p>{formatSessionDate(row.starts_at)}{row.professional?` · ${String(row.professional)}`:""}</p></div><div className="participant-session-actions">{row.link&&<a className="primary" href={String(row.link)} target="_blank" rel="noreferrer">Entrar a la sesión ↗</a>}{row.recording_url&&<a className="secondary" href={String(row.recording_url)} target="_blank" rel="noreferrer">Ver grabación ↗</a>}</div></article>)}</section>}</>}

function ParticipantMeeting({meeting,act}:{meeting:Row|null|undefined;act:(x:Row)=>Promise<unknown>}){
  const [saving,setSaving]=useState(false);const status=String(meeting?.status||"");const canRequest=!meeting||status==="rejected";
  async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setSaving(true);const form=e.currentTarget;const values=new FormData(form);try{await act({action:"meeting.request",requestedStart:new Date(String(values.get("requestedStart"))).toISOString(),topic:values.get("topic")});form.reset()}finally{setSaving(false)}}
  return <><Title eyebrow="BENEFICIO EXCLUSIVO PROYECTO 90" title="Tu reunión 1:1 con el Moya" copy="Durante tus 90 días tienes una reunión personal para revisar tu proceso, resolver dudas y definir próximos pasos."/>{meeting&&!canRequest&&<article className={`meeting-status-card ${status}`}><div className="meeting-status-icon">{status==="pending"?"⌛":"✓"}</div><div><span className="eyebrow">{status==="pending"?"SOLICITUD ENVIADA":status==="rescheduled"?"NUEVO HORARIO CONFIRMADO":"REUNIÓN CONFIRMADA"}</span><h2>{status==="pending"?"El Moya ya recibió tu solicitud":formatMeetingDate(meeting.confirmed_start||meeting.requested_start)}</h2>{status==="pending"?<p>El Moya revisará el horario y te notificará a la brevedad cuando esté confirmado. Si necesita cambiarlo, te contactará con el horario definitivo.</p>:<p>{meeting.admin_note?String(meeting.admin_note):"Este es el horario definitivo de tu reunión personal."}</p>}<div className="meeting-topic"><b>Tema de la reunión</b><span>{String(meeting.topic)}</span></div>{status==="pending"?<small>Horario solicitado: {formatMeetingDate(meeting.requested_start)}</small>:meeting.meeting_link&&<a className="primary meeting-join-link" href={String(meeting.meeting_link)} target="_blank" rel="noreferrer">Entrar a la videollamada ↗</a>}</div></article>}{canRequest&&<section className="meeting-booking-grid"><article className="meeting-benefit"><span className="eyebrow">1 REUNIÓN DURANTE EL PROGRAMA</span><h2>Propón tu horario</h2><p>Elige una fecha con al menos 48 horas de anticipación. La solicitud no queda confirmada automáticamente: el Moya revisará su agenda y te responderá a la brevedad.</p><ul><li>Revisión personal de tu avance</li><li>Dudas sobre entrenamiento, alimentación y hábitos</li><li>Próximos pasos para sostener el proceso</li></ul></article><form className="meeting-request-form" onSubmit={submit}>{status==="rejected"&&<div className="meeting-rejected-note"><b>Tu solicitud anterior no pudo confirmarse.</b><p>{String(meeting?.admin_note||"Puedes proponer un nuevo horario.")}</p></div>}<label>Fecha y hora que prefieres<input name="requestedStart" type="datetime-local" min={minimumMeetingLocal()} required/></label><label>¿Qué te gustaría conversar?<textarea name="topic" placeholder="Cuéntale brevemente al Moya qué quieres revisar en la reunión." required/></label><p className="meeting-rule">La plataforma solo permite horarios con 48 horas o más de anticipación.</p><button className="primary" disabled={saving}>{saving?"Enviando…":"Solicitar reunión 1:1"}</button></form></section>}</>
}

function MeetingManager({rows,act}:{rows:Row[];act:(x:Row)=>Promise<unknown>}){
  const pending=rows.filter(x=>x.status==="pending");const agenda=rows.filter(x=>["confirmed","rescheduled"].includes(String(x.status))).sort((a,b)=>Date.parse(String(a.confirmed_start))-Date.parse(String(b.confirmed_start)));
  return <><Title eyebrow="AGENDA PERSONAL DEL MOYA" title="Reuniones 1:1" copy="Confirma el horario, registra el enlace de videollamada y prepara la invitación de calendario para el alumno."/><section className="stats-grid four meeting-stats"><Metric label="Pendientes" value={String(pending.length)} note="Requieren respuesta"/><Metric label="Confirmadas" value={String(agenda.length)} note="En tu agenda" green/><Metric label="Reprogramadas" value={String(rows.filter(x=>x.status==="rescheduled").length)} note="Con nuevo horario"/><Metric label="Rechazadas" value={String(rows.filter(x=>x.status==="rejected").length)} note="Pueden volver a solicitar"/></section><div className="section-heading"><div><span className="eyebrow">NOTIFICACIONES</span><h2>Solicitudes pendientes</h2></div></div>{pending.length===0?<Empty title="No hay solicitudes pendientes" copy="Cuando un alumno solicite su reunión aparecerá aquí."/>:<section className="meeting-request-list">{pending.map(row=><MeetingReviewCard key={String(row.id)} row={row} act={act}/>)}</section>}<div className="section-heading"><div><span className="eyebrow">CALENDARIO 1:1</span><h2>Tu agenda confirmada</h2></div></div>{agenda.length===0?<article className="panel"><p className="empty-copy">Aún no hay reuniones confirmadas.</p></article>:<section className="meeting-agenda">{agenda.map(row=><article className="next-session confirmed-meeting" key={String(row.id)}><SessionDate row={{starts_at:row.confirmed_start}}/><div><span className="eyebrow">{row.status==="rescheduled"?"REPROGRAMADA":"CONFIRMADA"}</span><h3>{`${row.first_name||""} ${row.last_name||""}`.trim()||String(row.email)}</h3><p>{formatMeetingDate(row.confirmed_start)} · {String(row.topic)}</p><small>{String(row.email)}</small>{row.admin_note&&<small>{String(row.admin_note)}</small>}</div><div className="confirmed-meeting-actions">{row.meeting_link&&<a className="primary" href={String(row.meeting_link)} target="_blank" rel="noreferrer">Abrir reunión ↗</a>}<a className="secondary" href={googleCalendarUrl(row)} target="_blank" rel="noreferrer">Google Calendar ↗</a></div></article>)}</section>}</>
}

function MeetingReviewCard({row,act}:{row:Row;act:(x:Row)=>Promise<unknown>}){
  const [saving,setSaving]=useState(false);
  async function submit(e:FormEvent<HTMLFormElement>,decision:"approve"|"reject"|"reschedule"){e.preventDefault();setSaving(true);const values=new FormData(e.currentTarget);const local=String(values.get("confirmedStart")||"");const confirmedStart=local?new Date(local).toISOString():"";const meetingLink=String(values.get("meetingLink")||"");const calendarWindow=decision==="reject"?null:window.open("about:blank","_blank");try{await act({action:"meeting.review",id:row.id,decision,adminNote:values.get("adminNote"),meetingLink,...(confirmedStart?{confirmedStart}:{})});if(calendarWindow)calendarWindow.location.href=googleCalendarUrl({...row,confirmed_start:confirmedStart||row.requested_start,meeting_link:meetingLink})}catch(error){calendarWindow?.close();throw error}finally{setSaving(false)}}
  return <article className="meeting-review-card"><div className="meeting-review-head"><div><span className="avatar">{initials(`${row.first_name||""} ${row.last_name||""}`)}</span><div><h3>{`${row.first_name||""} ${row.last_name||""}`.trim()||String(row.email)}</h3><p>{String(row.email)} <button className="copy-email" onClick={()=>navigator.clipboard.writeText(String(row.email))}>Copiar correo</button></p></div></div><Status text="Pendiente"/></div><div className="meeting-request-details"><div><small>HORARIO SOLICITADO</small><b>{formatMeetingDate(row.requested_start)}</b></div><div><small>TEMA</small><b>{String(row.topic)}</b></div></div><div className="meeting-review-actions"><details className="meeting-confirm"><summary>✓ Aprobar y agendar</summary><form onSubmit={e=>submit(e,"approve")}><label>Horario definitivo<input name="confirmedStart" type="datetime-local" min={toLocalDateTime(new Date().toISOString())} defaultValue={toLocalDateTime(row.requested_start)} required/></label><label>Enlace de Google Meet, Zoom u otro<input name="meetingLink" type="url" placeholder="https://meet.google.com/…" required/></label><label>Mensaje para el alumno<textarea name="adminNote" placeholder="Ej. Nos vemos en este horario. Llega con tus dudas."/></label><label className="calendar-confirm"><input type="checkbox" required/> Agendaré esta reunión en mi calendario con el alumno como invitado.</label><button className="primary" disabled={saving}>{saving?"Confirmando…":"Confirmar y abrir Google Calendar"}</button></form></details><details><summary>Reprogramar</summary><form onSubmit={e=>submit(e,"reschedule")}><label>Nuevo horario<input name="confirmedStart" type="datetime-local" min={toLocalDateTime(new Date().toISOString())} required/></label><label>Enlace de Google Meet, Zoom u otro<input name="meetingLink" type="url" placeholder="https://meet.google.com/…" required/></label><label>Mensaje para el alumno<textarea name="adminNote" placeholder="Ej. Te propongo este nuevo horario."/></label><label className="calendar-confirm"><input type="checkbox" required/> Agendaré esta reunión en mi calendario con el alumno como invitado.</label><button className="secondary" disabled={saving}>Reprogramar y abrir Google Calendar</button></form></details><details><summary>Rechazar</summary><form onSubmit={e=>submit(e,"reject")}><label>Motivo<textarea name="adminNote" placeholder="Explícale brevemente por qué no puede confirmarse." required/></label><button className="danger-button" disabled={saving}>Rechazar solicitud</button></form></details></div></article>
}


function ParticipantArea({data,screen,act}:{data:AppData;screen:string;act:(x:Row)=>Promise<unknown>}){const programs=data.programs||[];const program=programs.find(p=>String(p.id)===String(data.assignedProgramId));const workouts=data.workouts||[];const assignedWorkouts=workouts.filter(w=>String(w.program_id)===String(data.assignedProgramId));const nutrition=data.nutrition;const adherence=Number(data.metrics?.[0]?.adherence||0);const day=Number(data.profile?.program_day||1);const graduated=Boolean(data.profile?.graduated);if(screen==="Escríbele al Moya")return <ContactMoya act={act}/>;if(screen==="Entrenamiento")return <ParticipantTraining data={data}/>;if(screen==="Sesiones")return <ParticipantSessions rows={data.sessions||[]}/>;if(screen==="Reunión 1:1")return <ParticipantMeeting meeting={data.meeting} act={act}/>;

if(screen==="Alimentación")return <><Title eyebrow="TU PLAN APROBADO" title="Mi alimentación" copy="Esta es la distribución diaria aprobada por tu nutricionista."/>{nutrition?<><article className="nutrition-objective"><div><span className="eyebrow">OBJETIVO DEL PLAN</span><h2>{String(nutrition.objective||"Plan nutricional personalizado")}</h2>{nutrition.notes&&<p>{String(nutrition.notes)}</p>}</div><Status text="approved"/></article><section className="participant-nutrition-summary"><div><small>PESO DE REFERENCIA</small><b>{data.profile?.weight?formatWeight(Number(data.profile.weight)):"Sin dato"}</b></div><div><small>ENERGÍA DIARIA</small><b>{formatNumber(Number(nutrition.calories||0),0)} kcal</b></div></section><MacroDistributionTable plan={nutrition} weight={Number(data.profile?.weight||0)} className="participant-macro-table"/><article className="panel plan-view"><div><h3>Tu guía nutricional adjunta</h3><p>{nutrition.pdf_key?"Consulta aquí el documento preparado para ti.":"El equipo todavía no ha adjuntado un documento."}</p></div>{nutrition.pdf_key&&<a className="primary" href={`/api/files?key=${encodeURIComponent(String(nutrition.pdf_key))}`} target="_blank">Abrir plan nutricional ↗</a>}</article></>:<Empty title="Plan en revisión" copy="Tu nutricionista debe aprobar la distribución antes de que puedas utilizarla."/>}</>;
if(screen==="Aprender")return <><Title eyebrow="APRENDER PARA NO DEPENDER" title="Clases y aprendizaje" copy="Las clases obligatorias están disponibles desde tu primer día."/>{(data.content||[]).length===0?<Empty title="Próximamente" copy="Los módulos aparecerán aquí cuando sean publicados."/>:<section className="learning-grid">{(data.content||[]).map(x=><article className={`learn-card ${Number(x.is_required)?"required-class":""}`} key={String(x.id)}><span className="learn-cover">▶</span><div><span className="tag">{Number(x.is_required)?"OBLIGATORIA · ":""}{String(x.category)}</span><h3>{String(x.title)}</h3><p>{String(x.description||"")}</p>{x.video_url&&<a href={String(x.video_url)} target="_blank" rel="noreferrer">Ver clase →</a>}</div></article>)}</section>}</>;
if(screen==="Progreso"){const latestWeight=data.checkpoints?.find(x=>x.weight!=null)?.weight??data.profile?.weight;return <><Title eyebrow="TU HISTORIA" title="Progreso" copy="Adherencia, peso y avance de tus 90 días."/><section className="stats-grid four"><Metric label="Adherencia" value={`${adherence}%`} note="Dato cargado desde Firme" green/><Metric label="Peso inicial" value={data.profile?.weight?formatWeight(Number(data.profile.weight)):"Sin dato"} note="Registrado al comenzar"/><Metric label="Último peso" value={latestWeight?formatWeight(Number(latestWeight)):"Sin reporte"} note="Tu registro más reciente"/><Metric label="Día actual" value={`${day} / 90`} note={graduated?"Programa completado":`${Math.round(day/90*100)}% del camino`}/></section><WeightReporter latestWeight={latestWeight} history={data.checkpoints||[]} act={act}/></>}
if(screen==="Mi Semana")return <ParticipantWeek program={program} workouts={assignedWorkouts} sessions={data.sessions||[]}/>;
const progress=Math.min(100,Math.round(day/90*100));const suggested=assignedWorkouts[suggestedWorkoutIndex(new Date().getDay(),assignedWorkouts.length)];return <><section className="participant-hero"><div><span className="eyebrow">TU PROYECTO 90</span><h1>Hola, {first(data.viewer.name)} 👋</h1><p>{graduated?"¡Completaste tus 90 días!":"Hoy solo tienes que seguir apareciendo."}</p></div><div className="day-ring" style={{background:`conic-gradient(var(--green) ${progress}%,#252b27 ${progress}%)`}}><div><strong>{day}</strong><span>de 90 días</span></div></div></section><div className="progress-line"><div style={{width:`${progress}%`}}/><span>{progress}% del camino</span><b>{graduated?"Graduado":`Día ${day} de 90`}</b></div><section className="stats-grid four home-overview"><Metric label="Hábitos" value={`${adherence}%`} note="Último dato de Firme" green/><Metric label="Rutina asignada" value={program?String(program.name):"Pendiente"} note={`${assignedWorkouts.length} sesiones cargadas`}/><DashboardNutrition nutrition={nutrition}/></section><div className="section-heading"><div><span className="eyebrow">HOY, SIN COMPLICARLO</span><h2>¿Qué hago ahora?</h2></div></div><section className="today-grid"><article className="focus-card"><span className="tag">{[1,2,4,6].includes(new Date().getDay())?"ENTRENAMIENTO DE HOY":"PRÓXIMO ENTRENAMIENTO"}</span><h3>{suggested?String(suggested.name):"Tu ruta está en preparación"}</h3><p>{program?String(program.name):"El equipo te asignará un programa."}</p></article><article className="week-card"><span className="tag">PRÓXIMA SESIÓN</span><h3>{data.sessions?.[0]?String(data.sessions[0].title):"Próximamente"}</h3><p>{data.sessions?.[0]?new Date(String(data.sessions[0].starts_at)).toLocaleString("es-CL"):"La agenda aparecerá aquí."}</p></article></section><ToolCards settings={data.settings}/></>}

function DashboardNutrition({nutrition}:{nutrition:Row|null|undefined}){
  if(!nutrition)return <article className="dashboard-nutrition pending"><div><span className="tag">NUTRICIÓN</span><h3>Plan en preparación</h3><p>Cuando el equipo asigne tus macros aparecerán aquí.</p></div></article>;
  return <article className="dashboard-nutrition"><div className="dashboard-nutrition-head"><span className="tag">NUTRICIÓN · OBJETIVO DIARIO</span><h3>{String(nutrition.objective||"Plan nutricional personalizado")}</h3></div><div className="dashboard-macros"><span><b>{String(nutrition.calories||0)}</b><small>kcal</small></span><span><b>{String(nutrition.protein||0)} g</b><small>proteínas</small></span><span><b>{String(nutrition.carbs||0)} g</b><small>carbohidratos</small></span><span><b>{String(nutrition.fats||0)} g</b><small>grasas</small></span></div></article>
}

function ParticipantWeek({program,workouts,sessions}:{program:Row|undefined;workouts:Row[];sessions:Row[]}){
  const now=new Date();const monday=new Date(now);monday.setHours(0,0,0,0);monday.setDate(now.getDate()-((now.getDay()+6)%7));
  const days=Array.from({length:7},(_,index)=>{const date=new Date(monday);date.setDate(monday.getDate()+index);return date});
  const workoutIndexByDay:Record<number,number>={1:0,2:1,4:2,6:3};
  const weekEnd=new Date(monday);weekEnd.setDate(monday.getDate()+7);
  const weekSessions=sessions.filter(row=>{const date=new Date(String(row.starts_at));return date>=monday&&date<weekEnd});
  return <><Title eyebrow="TU AGENDA DE ESTA SEMANA" title="Mi semana" copy="Aquí ves qué entrenamiento corresponde cada día, tus descansos y las sesiones en vivo del programa."/><section className="week-summary panel"><div><span className="eyebrow">RUTINA ASIGNADA</span><h2>{program?String(program.name):"Pendiente de asignación"}</h2></div><div className="week-summary-pills"><span>{Math.min(4,workouts.length)} entrenamientos</span><span>{weekSessions.length} {weekSessions.length===1?"sesión en vivo":"sesiones en vivo"}</span></div></section><section className="weekly-agenda">{days.map(date=>{const jsDay=date.getDay();const workoutIndex=workoutIndexByDay[jsDay];const workout=workoutIndex==null?undefined:workouts[workoutIndex];const daySessions=weekSessions.filter(row=>sameLocalDay(new Date(String(row.starts_at)),date));const today=sameLocalDay(date,now);return <article className={`agenda-day ${today?"today":""}`} key={date.toISOString()}><header><span>{date.toLocaleDateString("es-CL",{weekday:"long"})}</span><b>{date.getDate()}</b>{today&&<em>HOY</em>}</header><div className="agenda-events">{workout&&<div className="agenda-event workout"><span>ENTRENAMIENTO · DÍA {workoutIndex+1}</span><b>{shortWorkoutName(workout.name)}</b><small>{String(program?.name||"")}</small></div>}{daySessions.map(row=><div className="agenda-event live" key={String(row.id)}><span>SESIÓN EN VIVO · {new Date(String(row.starts_at)).toLocaleTimeString("es-CL",{hour:"2-digit",minute:"2-digit"})}</span><b>{String(row.title)}</b><small>{String(row.professional||"Equipo Proyecto 90")}</small>{row.link&&<a href={String(row.link)} target="_blank" rel="noreferrer">Entrar ↗</a>}</div>)}{!workout&&daySessions.length===0&&<div className="agenda-rest"><span>RECUPERACIÓN</span><p>Descanso o movilidad suave.</p></div>}</div></article>})}</section><p className="week-guidance">Esta es la distribución sugerida: Día 1 lunes, Día 2 martes, Día 3 jueves y Día 4 sábado. Si necesitas mover una sesión, puedes abrir cualquier día desde Entrenamiento.</p></>
}

function ParticipantTraining({data}:{data:AppData}){
  const programs=data.programs||[];
  const workouts=data.workouts||[];
  const blocks=data.workoutBlocks||[];
  const overrides=new Map((data.userWorkoutOverrides||[]).map(row=>[String(row.workout_exercise_id),row]));
  const links=(data.workoutExercises||[]).map(link=>{const custom=overrides.get(String(link.id));return custom?{...link,sets:custom.sets,reps:custom.reps,rest_seconds:custom.rest_seconds,notes:custom.notes,personalized:true}:link});
  const assigned=programs.find(p=>String(p.id)===String(data.assignedProgramId));
  const alternatives=programs.filter(p=>String(p.id)!==String(data.assignedProgramId));
  const [alternativeId,setAlternativeId]=useState(String(alternatives[0]?.id||""));
  const alternative=alternatives.find(p=>String(p.id)===alternativeId)||alternatives[0];
  return <><Title eyebrow="TU ENTRENAMIENTO" title={assigned?String(assigned.name):"Entrenamiento pendiente"} copy="Ve solo la sesión que toca. Puedes cambiar de día o explorar otra rutina cuando lo necesites."/>{assigned?<section className="assigned-training"><div className="assigned-training-head"><div><span className="eyebrow">TU RUTINA ASIGNADA</span><h2>{String(assigned.name)}</h2><p>{String(assigned.level)} · {String(assigned.location)}</p></div><span className="assigned-pill">✓ Recomendada para ti</span></div><ProgramWorkoutNavigator key={String(assigned.id)} program={assigned} workouts={workouts.filter(w=>String(w.program_id)===String(assigned.id))} blocks={blocks} links={links} suggested/></section>:<Empty title="Aún no tienes una rutina asignada" copy="El equipo seleccionará la ruta recomendada para ti."/>}{alternatives.length>0&&<details className="program-explorer"><summary><div><span className="eyebrow">OPCIONAL</span><b>Explorar otras rutinas</b><small>{alternatives.length} alternativas disponibles</small></div><span>＋</span></summary><div className="alternative-program-tabs">{alternatives.map(p=><button key={String(p.id)} className={String(p.id)===String(alternative?.id)?"active":""} onClick={()=>setAlternativeId(String(p.id))}><b>{String(p.name)}</b><small>{String(p.level)} · {String(p.location)}</small></button>)}</div>{alternative&&<ProgramWorkoutNavigator key={String(alternative.id)} program={alternative} workouts={workouts.filter(w=>String(w.program_id)===String(alternative.id))} blocks={blocks} links={links}/>}</details>}</>
}

function ProgramWorkoutNavigator({program,workouts,blocks,links,suggested=false}:{program:Row;workouts:Row[];blocks:Row[];links:Row[];suggested?:boolean}){
  const weekday=new Date().getDay();
  const suggestedMap=[0,0,1,2,2,3,3];
  const suggestedIndex=suggested?Math.min(Math.max(0,workouts.length-1),suggestedMap[weekday]):0;
  const [selectedId,setSelectedId]=useState(String(workouts[suggestedIndex]?.id||workouts[0]?.id||""));
  const selected=workouts.find(w=>String(w.id)===selectedId)||workouts[0];
  const todayNames=["domingo","lunes","martes","miércoles","jueves","viernes","sábado"];
  const trainingToday=[1,2,4,6].includes(weekday);
  if(workouts.length===0)return <p className="empty-copy">Las sesiones de {String(program.name)} están en preparación.</p>;
  return <div className="workout-navigator">{suggested&&<div className="today-workout-note"><span>{trainingToday?"HOY":"PRÓXIMA SESIÓN"}</span><div><b>{trainingToday?`Hoy es ${todayNames[weekday]}: esta es tu sesión sugerida.`:`Hoy es ${todayNames[weekday]}: te dejamos preparada la próxima sesión.`}</b><small>Si tu semana cambió, selecciona otro día abajo.</small></div></div>}<div className="workout-day-tabs" role="tablist" aria-label={`Días de ${String(program.name)}`}>{workouts.map((w,i)=>{const active=String(w.id)===String(selected?.id);return <button role="tab" aria-selected={active} className={active?"active":""} key={String(w.id)} onClick={()=>setSelectedId(String(w.id))}><span>DÍA {i+1}{suggested&&i===suggestedIndex?<em>{trainingToday?"HOY":"PRÓXIMA"}</em>:""}</span><b>{shortWorkoutName(w.name)}</b></button>})}</div>{selected&&<div className="selected-workout" role="tabpanel"><ParticipantWorkoutCard workout={selected} blocks={blocks} links={links}/></div>}</div>
}

function WeightReporter({latestWeight,history,act}:{latestWeight:unknown;history:Row[];act:(x:Row)=>Promise<unknown>}){
  const [saving,setSaving]=useState(false);
  async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setSaving(true);const form=e.currentTarget;try{await act({action:"weight.save",weight:new FormData(form).get("weight")});form.reset()}finally{setSaving(false)}}
  return <section className="weight-progress-grid"><article className="panel weight-report"><div><span className="eyebrow">SEGUIMIENTO PERSONAL</span><h2>Reportar mi peso</h2><p>Registra tu peso cuando quieras actualizar tu avance. El equipo verá siempre tu último reporte.</p></div><form onSubmit={submit}><label>Peso actual (kg)<input name="weight" type="number" min="30" max="300" step="0.1" placeholder={latestWeight?String(latestWeight):"Ej. 78,5"} required/></label><button className="primary" disabled={saving}>{saving?"Guardando…":"Guardar peso"}</button></form></article><article className="panel weight-history"><span className="eyebrow">ÚLTIMOS REGISTROS</span><h2>Historial de peso</h2>{history.filter(x=>x.weight!=null).slice(0,5).map(x=><div className="weight-history-row" key={String(x.id)}><b>{formatWeight(Number(x.weight))}</b><span>Día {String(x.day||1)}</span><small>{x.completed_at?new Date(String(x.completed_at)).toLocaleDateString("es-CL"):""}</small></div>)}{!history.some(x=>x.weight!=null)&&<p className="empty-copy">Aún no has reportado un nuevo peso.</p>}</article></section>
}

function ParticipantWorkoutCard({workout,blocks,links}:{workout:Row;blocks:Row[];links:Row[]}){
  const workoutBlocks=blocks.filter(x=>String(x.workout_id)===String(workout.id));
  const workoutLinks=links.filter(x=>String(x.workout_id)===String(workout.id));
  const known=new Set(workoutBlocks.map(x=>String(x.id)));
  const ungrouped=workoutLinks.filter(x=>!x.block_id||!known.has(String(x.block_id)));
  return <article className="workout-user"><span className="eyebrow">MES {String(workout.month)} · SEMANA {String(workout.week)}</span><h2>{String(workout.name)}</h2>{workout.progression&&<p className="progression-note"><b>Progresión semanal</b>{String(workout.progression)}</p>}{workoutBlocks.map((block,i)=><section className="workout-block participant-block" key={String(block.id)}><div className="workout-block-head"><div><span className="block-order">BLOQUE {i+1}</span><h4>{String(block.name)}</h4><BlockSummary block={block}/></div></div>{block.notes&&<p className="block-instructions">{String(block.notes)}</p>}<div className="block-exercises">{workoutLinks.filter(x=>String(x.block_id)===String(block.id)).map((x,j)=><ParticipantExerciseRow key={String(x.id)} item={x} index={j}/>)}</div></section>)}{ungrouped.length>0&&<section className="workout-block participant-block ungrouped"><div className="workout-block-head"><div><span className="block-order">EXTRA</span><h4>Ejercicios adicionales</h4></div></div>{ungrouped.map((x,i)=><ParticipantExerciseRow key={String(x.id)} item={x} index={i}/>)}</section>}</article>
}

function ParticipantExerciseRow({item,index}:{item:Row;index:number}){return <div className="exercise-row"><span className="number">{index+1}</span><div><h3>{String(item.exercise_name)}{item.personalized&&<em className="personalized-pill">Ajustado para ti</em>}</h3><p>{exerciseDetail(item)}</p>{usefulExerciseNote(item)&&<small className="student-note">{usefulExerciseNote(item)}</small>}</div>{item.youtube_url?<a className="secondary technique-link" href={String(item.youtube_url)} target="_blank" rel="noreferrer" aria-label={`Ver técnica de ${String(item.exercise_name)} en YouTube`}>Ver técnica en YouTube ▶</a>:<span className="secondary technique-link unavailable" aria-disabled="true">Video pendiente</span>}</div>}

function BlockSummary({block}:{block:Row}){const parts=[`${Number(block.rounds||1)} ${Number(block.rounds||1)===1?"ronda":"rondas"}`,Number(block.work_seconds)>0?`${String(block.work_seconds)} segundos de trabajo`:"",Number(block.rest_seconds)>0?`${String(block.rest_seconds)} segundos de descanso`:""];return <div className="block-badges">{parts.filter(Boolean).map(x=><span className="block-badge" key={x}>{x}</span>)}</div>}
function exerciseDetail(item:Row){const sets=Number(item.sets||1);const base=sets>1?`${sets} series × ${String(item.reps||"")}`:String(item.reps||"");return `${base}${Number(item.rest_seconds)>0?` · ${String(item.rest_seconds)} segundos de descanso`:""}`}
function usefulExerciseNote(item:Row){const note=String(item.notes||"").trim();return /^(Calentamiento|Circuito|Finisher|Abdomen|Extra opcional|HIIT|Vuelta a la calma)( ·.*)?$/i.test(note)?"":note}
function numberValue(value:unknown){const parsed=Number(value);return value==null||value===""||!Number.isFinite(parsed)?null:parsed}
function formatWeight(value:number){return `${value.toLocaleString("es-CL",{minimumFractionDigits:value%1?1:0,maximumFractionDigits:1})} kg`}
function nutritionWeight(row:Row){const value=Number(row.initial_weight??row.weight??0);return Number.isFinite(value)&&value>0?value:0}
function nutritionStatusKey(row:Row):"missing"|"review"|"approved"{if(!row.nutrition_id)return "missing";return String(row.review_status)==="approved"?"approved":"review"}
function formatNumber(value:number,digits:number){return Number.isFinite(value)?value.toLocaleString("es-CL",{minimumFractionDigits:digits,maximumFractionDigits:digits}):"—"}
function shortWorkoutName(value:unknown){const name=String(value||"Sesión");return name.replace(/^Día\s+\d+\s*[·:–-]\s*/i,"")}
function suggestedWorkoutIndex(weekday:number,length:number){const map=[0,0,1,2,2,3,3];return Math.min(Math.max(0,length-1),map[weekday])}
function sameLocalDay(a:Date,b:Date){return a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth()&&a.getDate()===b.getDate()}
function formatSessionDate(value:unknown){return new Date(String(value)).toLocaleString("es-CL",{weekday:"long",day:"numeric",month:"long",year:"numeric",hour:"2-digit",minute:"2-digit"})}
function formatMeetingDate(value:unknown){return new Date(String(value)).toLocaleString("es-CL",{weekday:"long",day:"numeric",month:"long",year:"numeric",hour:"2-digit",minute:"2-digit"})}
function googleCalendarUrl(row:Row){const start=new Date(String(row.confirmed_start||row.requested_start));const end=new Date(start.getTime()+45*60*1000);const stamp=(date:Date)=>date.toISOString().replace(/[-:]/g,"").replace(/\.\d{3}Z$/,"Z");const name=`${row.first_name||""} ${row.last_name||""}`.trim()||String(row.email||"Alumno");const link=String(row.meeting_link||"");const params=new URLSearchParams({action:"TEMPLATE",text:`Proyecto 90 · Reunión 1:1 con ${name}`,dates:`${stamp(start)}/${stamp(end)}`,details:`Tema: ${String(row.topic||"Seguimiento Proyecto 90")}\n\nEnlace de videollamada: ${link}`,location:link,add:String(row.email||"")});return `https://calendar.google.com/calendar/render?${params.toString()}`}
function minimumMeetingLocal(){return toLocalDateTime(new Date(Date.now()+48*60*60*1000).toISOString())}
function toLocalDateTime(value:unknown){if(!value)return "";const raw=String(value);if(!raw.endsWith("Z"))return raw.slice(0,16);const date=new Date(raw);return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)}

function Editor({modal,context,data,close,act}:{modal:Exclude<Modal,null>;context:Row;data:AppData;close:()=>void;act:(x:Row)=>Promise<unknown>}){const [saving,setSaving]=useState(false);const [fileKey,setFileKey]=useState(String(context.pdf_key||""));const [uploading,setUploading]=useState(false);useEffect(()=>setFileKey(String(context.pdf_key||"")),[context.id,context.pdf_key]);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setSaving(true);const form=new FormData(e.currentTarget);const values=Object.fromEntries(form.entries());try{await act({...values,action:actionFor(modal),...(["participant-edit","workout-edit","block-edit","exercise-edit","attach-edit","session-edit"].includes(modal)?{id:context.id}:{}),...(modal==="workout"?{programId:context.id}:{}),...(modal==="block"?{workoutId:context.id}:{}),...(modal==="attach"?{workoutId:context.id,blockId:context.block_id||""}:{}),...(modal==="nutrition"?{userId:context.id,pdfKey:fileKey}:{}),...(modal==="adherence"?{userId:context.id}:{})});close()}finally{setSaving(false)}}async function upload(file:File){setUploading(true);const fd=new FormData();fd.set("file",file);fd.set("userId",String(context.id));const r=await fetch("/api/files",{method:"POST",body:fd});const j=await r.json();setUploading(false);if(!r.ok)throw new Error(j.error);setFileKey(j.key)}return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><section className="editor-modal"><div className="modal-head"><div><span className="eyebrow">EDITOR PROYECTO 90</span><h2>{modalTitle(modal,context)}</h2></div><button onClick={close}>×</button></div><form onSubmit={submit}><Fields modal={modal} context={context} data={data}/>{modal==="nutrition"&&<label className="upload">Plan nutricional PDF<input type="file" accept="application/pdf" onChange={e=>e.target.files?.[0]&&upload(e.target.files[0])}/><span>{uploading?"Subiendo…":fileKey?"✓ PDF cargado":"＋ Subir PDF (máx. 10 MB)"}</span></label>}<div className="editor-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={saving||uploading}>{saving?"Guardando…":"Guardar cambios"}</button></div></form></section></div>}

function NutritionEditorFields({context}:{context:Row}){
  const weight=nutritionWeight(context);const [calories,setCalories]=useState(Number(context.calories||0));const [protein,setProtein]=useState(Number(context.protein||0));const [carbs,setCarbs]=useState(Number(context.carbs||0));const [fats,setFats]=useState(Number(context.fats||0));
  const plan:Row={calories,protein,carbs,fats};
  return <><p className="modal-context"><b>{`${context.first_name||""} ${context.last_name||""}`}</b> · al guardar, esta versión quedará pendiente de aprobación antes de mostrarse al alumno.</p><section className="nutrition-editor-overview"><div><small>PESO DEL FORMULARIO</small><b>{weight?formatWeight(weight):"Sin dato"}</b><span>Base para calcular gramos por kilo.</span></div><label>Calorías sugeridas<input name="calories" type="number" min="1" step="1" value={calories||""} onChange={e=>setCalories(Number(e.target.value))} required/></label></section><Field n="nutritionObjective" l="Objetivo del plan" placeholder="Ej. Déficit calórico moderado y mantener masa muscular" d={context.nutrition_objective||context.objective} required/><div className="nutrition-macro-inputs"><label>Proteínas (g)<input name="protein" type="number" min="0" step="0.1" value={protein||""} onChange={e=>setProtein(Number(e.target.value))} required/></label><label>Carbohidratos (g)<input name="carbs" type="number" min="0" step="0.1" value={carbs||""} onChange={e=>setCarbs(Number(e.target.value))} required/></label><label>Lípidos / grasas (g)<input name="fats" type="number" min="0" step="0.1" value={fats||""} onChange={e=>setFats(Number(e.target.value))} required/></label></div><div className="nutrition-live-calculation"><span className="eyebrow">CÁLCULO AUTOMÁTICO</span><MacroDistributionTable plan={plan} weight={weight}/><p>Proteínas y carbohidratos aportan 4 kcal por gramo; los lípidos aportan 9 kcal por gramo. Los porcentajes se calculan respecto de las calorías sugeridas.</p></div><Area n="notes" l="Indicaciones para el alumno" d={context.nutrition_notes}/><Field n="reviewDate" l="Fecha de revisión" type="date" d={context.review_date}/></>
}

function Fields({modal,context,data}:{modal:Exclude<Modal,null>;context:Row;data:AppData}){if(modal==="professional")return <><p className="modal-context"><b>Acceso profesional sin pago.</b> Esta persona podrá ingresar con el correo registrado y solo verá los módulos de su especialidad.</p><div className="form-grid two"><Field n="firstName" l="Nombre" required/><Field n="lastName" l="Apellido"/><Field n="email" l="Correo de acceso a Proyecto 90" type="email" required/><Field n="city" l="Ciudad"/><Select n="professionalType" l="Especialidad" opts={["nutrition","training","both"]} labels={["Nutricionista","Preparador físico","Ambos"]}/></div></>;
if(modal==="participant"||modal==="participant-edit")return <><p className="modal-context"><b>Acceso a Proyecto 90.</b> Este será el correo con el que el participante ingresará a la plataforma. Su Día 1 comienza al crear este registro.</p><div className="form-grid two"><Field n="firstName" l="Nombre" d={context.first_name} required/><Field n="lastName" l="Apellido" d={context.last_name}/><Field n="email" l="Correo de acceso a Proyecto 90" d={context.email} type="email" disabled={modal==="participant-edit"} required/><Field n="city" l="Ciudad" d={context.city}/><Field n="objective" l="Objetivo principal" d={context.objective}/><Field n="trainingDays" l="Días disponibles" d={context.training_days||3} type="number"/></div><div className="form-grid two"><Select n="location" l="Lugar" d={context.preferred_location} opts={["Casa","Gimnasio","Ambos"]}/><Select n="activityLevel" l="Actividad" d={context.activity_level} opts={["Sedentario","Mixto","Activo"]}/>{modal==="participant"&&<Select n="programId" l="Rutina asignada" opts={(data.programs||[]).map(x=>String(x.id))} labels={(data.programs||[]).map(x=>String(x.name))}/>} {modal==="participant-edit"&&<Select n="status" l="Estado" d={context.status} opts={["invited","onboarding","review","configuration","active","finished"]}/>}</div><Area n="restrictions" l="Restricciones alimentarias" d={context.dietary_restrictions}/><Area n="motivation" l="¿Por qué quiere hacer Proyecto 90?" d={context.motivation}/> </>;
if(modal==="adherence")return <><p className="modal-context"><b>{`${context.first_name||""} ${context.last_name||""}`}</b> · dato manual desde Hábitos Firme</p><div className="form-grid two"><Field n="adherence" l="Porcentaje de adherencia" type="number" d={context.adherence} required/><Field n="date" l="Fecha del registro" type="date" d={new Date().toISOString().slice(0,10)} required/></div></>;
if(modal==="program")return <><Field n="name" l="Nombre del programa" placeholder="Ej. Casa Avanzado" required/><div className="form-grid two"><Select n="level" l="Nivel" opts={["Inicial","Intermedio","Avanzado"]}/><Select n="location" l="Lugar" opts={["Casa","Gimnasio","Ambos"]}/></div></>;
if(modal==="workout"||modal==="workout-edit")return <><p className="modal-context">{modal==="workout"?<>Programa: <b>{String(context.name)}</b></>:<>Edita la rutina y los cambios aparecerán en la vista del participante.</>}</p><Field n="name" l="Nombre de la rutina" placeholder="Ej. Día 1 · Fuerza base" d={modal==="workout-edit"?context.name:""} required/><div className="form-grid two"><Field n="month" l="Mes" type="number" d={modal==="workout-edit"?context.month:1}/><Field n="week" l="Semana" type="number" d={modal==="workout-edit"?context.week:1}/></div><Area n="progression" l="Progresión semanal de la rutina" d={context.progression}/></>;
if(modal==="exercise"||modal==="exercise-edit")return <><p className="modal-context"><b>El video es obligatorio.</b> Este enlace aparecerá junto al ejercicio en todas las rutinas del alumno.</p><div className="form-grid two"><Field n="name" l="Nombre del ejercicio" d={context.name} required/><Field n="youtubeUrl" l="Video de técnica en YouTube" placeholder="https://youtube.com/watch?v=…" type="url" d={context.youtube_url} required/><Field n="category" l="Categoría" placeholder="Piernas, empuje…" d={context.category}/><Select n="level" l="Nivel" d={context.level} opts={["Inicial","Intermedio","Avanzado"]}/></div><Area n="description" l="Descripción" d={context.description}/><Area n="technique" l="Técnica" d={context.technique}/><Area n="commonErrors" l="Errores frecuentes" d={context.common_errors}/><div className="form-grid two"><Field n="regression" l="Regresión" d={context.regression}/><Field n="progression" l="Progresión" d={context.progression}/></div></>;
if(modal==="block"||modal==="block-edit")return <><p className="modal-context">{modal==="block"?<>Rutina: <b>{String(context.name)}</b></>:<>Define cómo se ejecuta este bloque; los cambios se muestran inmediatamente al alumno.</>}</p><Field n="name" l="Nombre del bloque" placeholder="Ej. Calentamiento, Circuito o Finisher" d={context.name} required/><div className="form-grid three"><Field n="rounds" l="Rondas" type="number" d={modal==="block-edit"?context.rounds:1}/><Field n="workSeconds" l="Trabajo por ejercicio (segundos)" type="number" d={context.work_seconds}/><Field n="restSeconds" l="Descanso (segundos)" type="number" d={context.rest_seconds}/></div><Area n="notes" l="Cómo ejecutar este bloque" d={context.notes}/></>;
if(modal==="attach"||modal==="attach-edit"){const workoutId=String(context.workout_id||context.id||"");const blocks=(data.workoutBlocks||[]).filter(x=>String(x.workout_id)===workoutId);return <><p className="modal-context">{modal==="attach"?<>Bloque: <b>{String(context.block_name||context.name)}</b></>:<>Ejercicio: <b>{String(context.exercise_name)}</b></>}</p><Select n="blockId" l="Bloque de la sesión" d={context.block_id} opts={["",...blocks.map(x=>String(x.id))]} labels={["Sin bloque",...blocks.map(x=>String(x.name))]}/>{modal==="attach"&&<Select n="exerciseId" l="Ejercicio de la biblioteca" opts={(data.exercises||[]).map(x=>String(x.id))} labels={(data.exercises||[]).map(x=>String(x.name))}/>}<p className="field-help">Las rondas y los tiempos generales se configuran en el bloque.</p><div className="form-grid three"><Field n="sets" l="Series dentro de cada ronda" type="number" d={modal==="attach-edit"?context.sets:1}/><Field n="reps" l="Repeticiones o tiempo" d={modal==="attach-edit"?context.reps:10}/><Field n="restSeconds" l="Descanso propio (segundos)" type="number" d={modal==="attach-edit"?context.rest_seconds:0}/></div><Area n="notes" l="Notas para el alumno" d={context.notes}/></>}
if(modal==="nutrition")return <NutritionEditorFields context={context}/>;
if(modal==="content")return <><div className="form-grid two"><Field n="title" l="Título" required/><Select n="category" l="Categoría" opts={["Hábitos","Nutrición","Entrenamiento","Sesiones"]}/></div><Area n="description" l="Descripción"/><Field n="videoUrl" l="Video YouTube no listado" type="url"/><Check n="isRequired" l="Clase obligatoria: disponible desde el Día 1"/><div className="form-grid two"><Field n="position" l="Orden" type="number" d="1"/><Field n="publishAt" l="Publicar desde" type="datetime-local"/></div></>;
return <><Field n="title" l="Nombre de la sesión" d={context.title} required/><div className="form-grid two"><Field n="professional" l="Profesional" d={context.professional}/><Field n="startsAt" l="Fecha y hora" type="datetime-local" d={toLocalDateTime(context.starts_at)} required/></div><Field n="link" l="Enlace en vivo" type="url" d={context.link}/><Field n="recordingUrl" l="Grabación" type="url" d={context.recording_url}/></>}

function Title({eyebrow,title,copy,action}:{eyebrow:string;title:string;copy:string;action?:React.ReactNode}){return <div className="admin-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{copy}</p></div>{action}</div>}
function Metric({label,value,note,green=false}:{label:string;value:string;note:string;green?:boolean}){return <article className={`metric ${green?"green":""}`}><div className="metric-head"><span className="metric-icon">{green?"✓":"◎"}</span><span>{label}</span></div><strong>{value}</strong><small>{note}</small></article>}
function Empty({title,copy,action}:{title:string;copy:string;action?:React.ReactNode}){return <article className="empty-state"><span className="icon-tile green">＋</span><h2>{title}</h2><p>{copy}</p>{action}</article>}
function Status({text}:{text:string}){const labels:Record<string,string>={invited:"Invitado",onboarding:"Onboarding",review:"En revisión",configuration:"Configuración",active:"Activo",finished:"Finalizado",pending_review:"Por revisar",approved:"Aprobado",rejected:"Rechazado","Sin plan":"Sin plan"};const shown=labels[text]||text;return <span className={`status ${text.toLowerCase().replace(/[\s_]+/g,"-")}`}>{shown}</span>}
function Field({n,l,d="",type="text",placeholder="",required=false,disabled=false}:{n:string;l:string;d?:unknown;type?:string;placeholder?:string;required?:boolean;disabled?:boolean}){return <label>{l}<input name={n} defaultValue={String(d||"")} type={type} placeholder={placeholder} required={required} disabled={disabled}/></label>}
function Area({n,l,d=""}:{n:string;l:string;d?:unknown}){return <label>{l}<textarea name={n} defaultValue={String(d||"")}/></label>}
function Check({n,l}:{n:string;l:string}){return <label className="check-field"><input name={n} type="checkbox"/> {l}</label>}
function Select({n,l,d="",opts,labels}:{n:string;l:string;d?:unknown;opts:string[];labels?:string[]}){return <label>{l}<select name={n} defaultValue={String(d||opts[0]||"")}>{opts.map((x,i)=><option value={x} key={x}>{labels?.[i]||x}</option>)}</select></label>}
function actionFor(m:Exclude<Modal,null>){return ({participant:"participant.create",professional:"professional.create","participant-edit":"participant.update",adherence:"adherence.save",program:"program.create",workout:"workout.create","workout-edit":"workout.update",block:"workout.block.create","block-edit":"workout.block.update",exercise:"exercise.create","exercise-edit":"exercise.update",attach:"workout.exercise.add","attach-edit":"workout.exercise.update",nutrition:"nutrition.save",content:"content.create",session:"session.create","session-edit":"session.update"} as Record<string,string>)[m]}
function modalTitle(m:Exclude<Modal,null>,c:Row){return ({participant:"Crear participante",professional:"Crear profesional","participant-edit":"Editar participante",adherence:"Cargar adherencia de Firme",program:"Crear programa",workout:"Agregar rutina","workout-edit":"Editar rutina",block:"Agregar bloque","block-edit":"Editar bloque",exercise:"Agregar ejercicio y video","exercise-edit":"Editar ejercicio",attach:`Agregar ejercicio a ${String(c.block_name||c.name||"rutina")}`,"attach-edit":`Editar ${String(c.exercise_name||"ejercicio")}`,nutrition:"Editar nutrición",content:"Publicar contenido",session:"Crear sesión","session-edit":"Editar sesión"} as Record<string,string>)[m]}
function onboardingIsComplete(data:AppData){if(data.profile?.completed_at)return true;const answers=new Map((data.responses||[]).map(row=>[String(row.question_id),String(row.answer||"").trim()]));const required=(data.questions||[]).filter(row=>Boolean(row.required));return required.length>0&&required.every(row=>Boolean(answers.get(String(row.id))))}
function initials(n:string){return n.split(" ").filter(Boolean).slice(0,2).map(x=>x[0]?.toUpperCase()).join("")||"90"} function first(n:string){return n.split(" ")[0]||"Moya"} function roleLabel(r:string){return r==="admin"?"Administrador":r==="professional"?"Profesional":r==="reviewer"?"Revisor · solo lectura":"Participante"}
